"""Data types a la carte: smart constructors bound by `Has`, Fix with a generic fold, free monads.  Run: python3 tests/run_alacarte.py"""
import os, subprocess, sys, tempfile
ROOT = os.path.dirname(os.path.abspath(__file__)) + "/.."
CASES = [
 ("a smart constructor builds in any language that holds the node", 'tuple Lit deriving show\n  value Int\ntuple Add[E] deriving show\n  left E\n  right E\ntuple Mul[E] deriving show\n  left E\n  right E\nunion type Arith = Lit | Add[Arith]\nunion type Full = Lit | Add[Full] | Mul[Full]\nfn lit[U Has[Lit]](n Int) U = Lit(n)\nfn add[U Has[Add[U]]](a U, b U) U = Add[U](a, b)\nfn mul[U Has[Mul[U]]](a U, b U) U = Mul[U](a, b)\n' + "x Full = add(lit(1), mul(lit(2), lit(3)))\nprintln(x)\ny Arith = add(lit(1), lit(2))\nprintln(y)\nprintln(lit[Full](5))\n", 0, "Add(left: Lit(value: 1), right: Mul(left: Lit(value: 2), right: Lit(value: 3)))\nAdd(left: Lit(value: 1), right: Lit(value: 2))\nLit(value: 5)"),
 ("a binding to a union that lacks the node", 'tuple Lit deriving show\n  value Int\ntuple Add[E] deriving show\n  left E\n  right E\ntuple Mul[E] deriving show\n  left E\n  right E\nunion type Arith = Lit | Add[Arith]\nunion type Full = Lit | Add[Full] | Mul[Full]\nfn lit[U Has[Lit]](n Int) U = Lit(n)\nfn add[U Has[Add[U]]](a U, b U) U = Add[U](a, b)\nfn mul[U Has[Mul[U]]](a U, b U) U = Mul[U](a, b)\n' + "y Arith = mul(lit(1), lit(2))\n", 2, "`Arith` has no `Mul[Arith]`"),
 ("an explicit type argument that lacks the node", 'tuple Lit deriving show\n  value Int\ntuple Add[E] deriving show\n  left E\n  right E\ntuple Mul[E] deriving show\n  left E\n  right E\nunion type Arith = Lit | Add[Arith]\nunion type Full = Lit | Add[Full] | Mul[Full]\nfn lit[U Has[Lit]](n Int) U = Lit(n)\nfn add[U Has[Add[U]]](a U, b U) U = Add[U](a, b)\nfn mul[U Has[Mul[U]]](a U, b U) U = Mul[U](a, b)\n' + "z = mul[Arith](lit[Arith](1), lit[Arith](2))\n", 2, "`Arith` has no `Mul[Arith]`"),
 ("a result type that lacks the node", 'tuple Lit deriving show\n  value Int\ntuple Add[E] deriving show\n  left E\n  right E\ntuple Mul[E] deriving show\n  left E\n  right E\nunion type Arith = Lit | Add[Arith]\nunion type Full = Lit | Add[Full] | Mul[Full]\nfn lit[U Has[Lit]](n Int) U = Lit(n)\nfn add[U Has[Add[U]]](a U, b U) U = Add[U](a, b)\nfn mul[U Has[Mul[U]]](a U, b U) U = Mul[U](a, b)\n' + "fn f() Arith = mul(lit(1), lit(2))\n", 2, "`Arith` has no `Mul[Arith]`"),
 ("a generic caller must carry the bound", 'tuple Lit deriving show\n  value Int\ntuple Add[E] deriving show\n  left E\n  right E\ntuple Mul[E] deriving show\n  left E\n  right E\nunion type Arith = Lit | Add[Arith]\nunion type Full = Lit | Add[Full] | Mul[Full]\nfn lit[U Has[Lit]](n Int) U = Lit(n)\nfn add[U Has[Add[U]]](a U, b U) U = Add[U](a, b)\nfn mul[U Has[Mul[U]]](a U, b U) U = Mul[U](a, b)\n' + "fn g[V](n Int) V = lit(n)\n", 2, "`V` is not known to have `Lit`"),
 ("a generic caller that carries the bound", 'tuple Lit deriving show\n  value Int\ntuple Add[E] deriving show\n  left E\n  right E\ntuple Mul[E] deriving show\n  left E\n  right E\nunion type Arith = Lit | Add[Arith]\nunion type Full = Lit | Add[Full] | Mul[Full]\nfn lit[U Has[Lit]](n Int) U = Lit(n)\nfn add[U Has[Add[U]]](a U, b U) U = Add[U](a, b)\nfn mul[U Has[Mul[U]]](a U, b U) U = Mul[U](a, b)\n' + "fn g[V Has[Lit]](n Int) V = lit(n)\nx Full = g(4)\nprintln(x)\n", 0, "Lit(value: 4)"),
 ("a bounded constructor returns the wrong node", 'tuple Lit deriving show\n  value Int\ntuple Add[E] deriving show\n  left E\n  right E\ntuple Mul[E] deriving show\n  left E\n  right E\nunion type Arith = Lit | Add[Arith]\nunion type Full = Lit | Add[Full] | Mul[Full]\nfn lit[U Has[Lit]](n Int) U = Lit(n)\nfn add[U Has[Add[U]]](a U, b U) U = Add[U](a, b)\nfn mul[U Has[Mul[U]]](a U, b U) U = Mul[U](a, b)\n' + "fn bad[U Has[Lit]](n Int) U = Add[U](lit(n), lit(n))\n", 2, "only known to hold what its `Has` bounds name"),
 ("a freer-monad program runs", 'enum Cmd[A]\n  Say(text String) Cmd[Unit]\n  Ask Cmd[String]\nenum Prog[A]\n  Pure(a A)\n  Bind[X](cmd Cmd[X], k (X) -> Prog[A])\n\nfn say(t String) Prog[Unit] = Bind(Say(t), (u) -> Pure(()))\nfn ask() Prog[String] = Bind(Ask, (s) -> Pure(s))\nfn then[A, B](p Prog[A], f (A) -> Prog[B]) Prog[B] = when p\n  Pure(a) -> f(a)\n  Bind(c, k) -> Bind(c, (x) -> then(k(x), f))\nfn exec[A](p Prog[A]) A = when p\n  Pure(a) -> a\n  Bind(c, k) -> when c\n    Say(t) ->\n      println(t)\n      exec(k(()))\n    Ask -> exec(k("bob"))\n\nhello = then(ask(), (n) -> say("hi ${n}"))\nexec(hello)\n' + "", 0, "hi bob"),
 ("a freer-monad command with the wrong result type", 'enum Cmd[A]\n  Say(text String) Cmd[Unit]\n  Ask Cmd[String]\nenum Prog[A]\n  Pure(a A)\n  Bind[X](cmd Cmd[X], k (X) -> Prog[A])\n\nfn say(t String) Prog[Unit] = Bind(Say(t), (u) -> Pure(()))\nfn ask() Prog[String] = Bind(Ask, (s) -> Pure(s))\nfn then[A, B](p Prog[A], f (A) -> Prog[B]) Prog[B] = when p\n  Pure(a) -> f(a)\n  Bind(c, k) -> Bind(c, (x) -> then(k(x), f))\nfn exec[A](p Prog[A]) A = when p\n  Pure(a) -> a\n  Bind(c, k) -> when c\n    Say(t) ->\n      println(t)\n      exec(k(()))\n    Ask -> exec(k("bob"))\n\nhello = then(ask(), (n) -> say("hi ${n}"))\nexec(hello)\n' + "fn bad() Prog[Int] = Bind(Say(\"x\"), (u) -> Pure(u + 1))\n", 2, ""),
 ("a call passed as an argument must build into a union that holds the node", 'tuple Lit deriving show\n  value Int\ntuple Add[E] deriving show\n  left E\n  right E\ntuple Mul[E] deriving show\n  left E\n  right E\nunion type Arith = Lit | Add[Arith]\nunion type Full = Lit | Add[Full] | Mul[Full]\nfn lit[U Has[Lit]](n Int) U = Lit(n)\nfn mul[U Has[Mul[U]]](a U, b U) U = Mul[U](a, b)\nfn show_full(x Full) String = "${x}"\nfn show_arith(x Arith) String = "${x}"\n\nprintln(show_arith(mul(lit(1), lit(2))))\n', 2, "`Arith` has no `Mul[Arith]`"),
 ("a call passed as an argument to a union that holds the node", 'tuple Lit deriving show\n  value Int\ntuple Add[E] deriving show\n  left E\n  right E\ntuple Mul[E] deriving show\n  left E\n  right E\nunion type Arith = Lit | Add[Arith]\nunion type Full = Lit | Add[Full] | Mul[Full]\nfn lit[U Has[Lit]](n Int) U = Lit(n)\nfn mul[U Has[Mul[U]]](a U, b U) U = Mul[U](a, b)\nfn show_full(x Full) String = "${x}"\nfn show_arith(x Arith) String = "${x}"\n\nprintln(show_full(mul(lit(1), lit(2))))\n', 0, "Add" if False else "Mul(left: Lit(value: 1), right: Lit(value: 2))"),
]
fails = []
for name, src, rc_want, word in CASES:
    for gc in (False, True):
        with tempfile.NamedTemporaryFile("w", suffix=".mxi", delete=False) as f:
            f.write(src)
        cmd = [sys.executable, "-m", "moxie"] + (["--gc"] if gc else []) + ["check" if rc_want == 2 else "run", f.name]
        r = subprocess.run(cmd, cwd=ROOT, capture_output=True, text=True)
        os.unlink(f.name)
        o = r.stdout + r.stderr
        ok = ((r.returncode != 0) if rc_want else r.returncode == 0) and word in o
        print(("ok    " if ok else "FAIL  ") + name + (" (gc)" if gc else "") + ("" if ok else f"  -> rc={r.returncode} {o.strip()[:240]}"))
        if not ok: fails.append(name)
print("FAILED" if fails else "all passed")
sys.exit(1 if fails else 0)
